<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class mgarmentsampling extends CI_Controller {    public function __construct() {        parent::__construct();        $this->load->model(CNFCOMPANY . "mgarmentsamplingmodel");        $this->load->helper('xssclean');        fnIfCheckUserLoggedIn();        $this->limit = LIMITPERPAGE;    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId = $this->uri->segment(4);        $ArrData['Edit'] = $this->uri->segment(5);        if ($VarId <> '' && base64_decode(urldecode($VarId))) {            $VarUserId = base64_decode(urldecode($VarId));            $ArrResults = $this->mgarmentsamplingmodel->fnGetInfo('', '', $VarUserId);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addeditgarmentsampling', $ArrData);    }    public function updateInfo() {        $VarUserInfo = fnGetUserLoggedInfo(1);        $VarCompanyId = $VarUserInfo['companyid'];        $ArrResult = array();        $Varrequirement = xssclean($this->input->post('gs'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($Varrequirement <> '') {            $ArrUpdateData = array('id' => $VarId, 'companyid' => $VarCompanyId, 'requirement' => $Varrequirement,                'status' => $VarStatus, 'updatedby' => $VarUserInfo['id'], 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mgarmentsamplingmodel->saveInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function manage() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarName = xssclean($this->input->post('gs'));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $VarAfilter = xssclean($this->input->post('afilter'));        $ArrDbCols = array('requirement', 'gs.status', 'u.contactname', 'gs.dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . 'mgarmentsampling/manage/';            $config['total_rows'] = $this->mgarmentsamplingmodel->fnCount($VarName, $VarStatus, $VarAfilter);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "gs.dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrFabricTypeList = $this->mgarmentsamplingmodel->fnList($VarName, $VarStatus, $this->limit, $offset, $sortby, $sortorder, $VarAfilter)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('GarmentSampling');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            foreach ($ArrFabricTypeList as $ObjFabric) {                $ArrFnlList[$i]['id'] = $ObjFabric->id;                $ArrFnlList[$i]['gsr'] = $ObjFabric->requirement;                $ArrFnlList[$i]['ub'] = $ObjFabric->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$ObjFabric->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i:s', strtotime($ObjFabric->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'managegarmentsampling');        }    }    function changemStatus() {        $VarActDeactOption = xssclean($this->input->post('actdeactFabType'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarActDeactOption <> '' && $VarCid <> '') {            $this->mgarmentsamplingmodel->fnChangeComStat($VarCid, $VarActDeactOption);        }        echo json_encode(array('errcode' => 1));        die;    }}